"""Make the B8.1 course badge image: a plain square PNG, generated by the project (Apache-2.0).

The guide's answer on Issue #55 (2026-11-18, P9b): a plain square PNG generated by the project
under Apache-2.0, its source kept in the B8.1 testdata folder, with a record of how it was made.
This script is that source and that record. It uses the Python standard library only, and no
third-party image or font.

Run from the repository root:

    python testdata/b8-1-template-course/make_badge.py            # write badge.png
    python testdata/b8-1-template-course/make_badge.py --dry-run  # say what it would write
    python testdata/b8-1-template-course/make_badge.py --check    # badge.png matches this script?

Undo: delete testdata/b8-1-template-course/badge.png (or restore it with git).
Exit codes: 0 = done, or the file matches; 1 = the file is missing or differs.
"""

from __future__ import annotations

import argparse
import struct
import sys
import zlib
from pathlib import Path

TARGET = Path(__file__).resolve().parent / "badge.png"

SIZE = 512  # pixels, square
BORDER = 32  # pixels
FILL = bytes((0x0F, 0x6C, 0xBD))  # blue
EDGE = bytes((0x0A, 0x3D, 0x6B))  # dark blue
SIGNATURE = b"\x89PNG\r\n\x1a\n"

DONE = "Wrote {path} ({size} x {size} pixels, {count} bytes)."
DRY_RUN = "Dry run: would write {path} ({size} x {size} pixels); nothing written."
MATCHES = "{path} matches make_badge.py."
DIFFERS = "{path} is missing or differs from make_badge.py. Run the script without options to rewrite it."


def pixels() -> bytes:
    """Raw image rows, each with PNG filter byte 0: a filled square inside a border."""
    edge_row = EDGE * SIZE
    inner_row = EDGE * BORDER + FILL * (SIZE - 2 * BORDER) + EDGE * BORDER
    rows = [
        edge_row if y < BORDER or y >= SIZE - BORDER else inner_row for y in range(SIZE)
    ]
    return b"".join(b"\x00" + row for row in rows)


def _chunk(kind: bytes, data: bytes) -> bytes:
    crc = zlib.crc32(kind + data) & 0xFFFFFFFF
    return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", crc)


def badge_png() -> bytes:
    header = struct.pack(
        ">IIBBBBB", SIZE, SIZE, 8, 2, 0, 0, 0
    )  # 8-bit RGB, no interlace
    return (
        SIGNATURE
        + _chunk(b"IHDR", header)
        + _chunk(b"IDAT", zlib.compress(pixels(), 9))
        + _chunk(b"IEND", b"")
    )


def matches(path: Path) -> bool:
    """Compare the decoded image, not the bytes: zlib builds may compress the same pixels
    differently."""
    try:
        data = path.read_bytes()
    except OSError:
        return False
    if not data.startswith(SIGNATURE):
        return False
    chunks: dict[bytes, bytes] = {}
    position = len(SIGNATURE)
    while position + 8 <= len(data):
        length, kind = struct.unpack(">I4s", data[position : position + 8])
        chunks[kind] = (
            chunks.get(kind, b"") + data[position + 8 : position + 8 + length]
        )
        position += 12 + length
    try:
        image = zlib.decompress(chunks.get(b"IDAT", b""))
    except zlib.error:
        return False
    return chunks.get(b"IHDR", b"")[:10] == struct.pack(">IIBB", SIZE, SIZE, 8, 2) and (
        image == pixels()
    )


def main(argv: list[str] | None = None, target: Path = TARGET) -> int:
    parser = argparse.ArgumentParser(description="Make the B8.1 course badge image.")
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument(
        "--dry-run", action="store_true", help="say what would be written"
    )
    mode.add_argument(
        "--check", action="store_true", help="check badge.png; write nothing"
    )
    args = parser.parse_args(argv)

    if args.dry_run:
        print(DRY_RUN.format(path=target, size=SIZE))
        return 0
    if args.check:
        ok = matches(target)
        print((MATCHES if ok else DIFFERS).format(path=target))
        return 0 if ok else 1
    data = badge_png()
    target.write_bytes(data)
    print(DONE.format(path=target, size=SIZE, count=len(data)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
